import path from 'path';
import chalk from 'chalk';
import JSON5 from 'json5';
import { resolveToken, retryOnAuthError } from '../core/credentials.js';
import { syncCapabilities } from '../core/capabilities.js';
import { scanFiles } from '../core/scanner.js';
import { runnableDirs } from '../core/project-layout.js';
import { pathToModule, toPosix } from '../core/snapshot.js';
import { readWd, existsWd, displayPath, toModulePath } from '../core/workdir.js';
import { runFunction, describeServerError } from '../api/endpoints.js';
import { createSpinner } from '../utils/spinner.js';
import { fatal } from '../utils/logger.js';
import { formatRunHeader, formatRunLogs, formatRunReturn } from '../core/run-output.js';

function parseJson5Inline(str, errorMsg) {
  try {
    return JSON5.parse(str);
  } catch (err) {
    fatal(`${errorMsg}: ${err.message}`);
  }
}

// `args` and `ctx` must be JSON objects; the server rejects anything else.
function requireObject(value, what, example) {
  if (value === undefined) return;
  if (typeof value === 'object' && value !== null && !Array.isArray(value)) return;
  const got = Array.isArray(value) ? 'an array' : value === null ? 'null' : `a ${typeof value}`;
  fatal(`${what} must be a JSON object, e.g. '${example}' — got ${got}.`);
}

function isRunnable(filePath, runnable) {
  return runnable.some((dir) =>
    filePath.startsWith(dir + path.sep) || filePath.startsWith(dir + '/')
  );
}

/**
 * Resolve `input` — a module name (`handlers/message`), a module path, or the
 * on-disk path (`tgcloud/handlers/message.js`) — to a POSIX module path.
 * `scanned` are the deployable files as POSIX module paths.
 * @returns {{ path: string } | { error: { kind: 'ambiguous'|'not-runnable'|'not-found', path?: string, candidates?: string[] } }}
 */
export function resolveRunnablePath(input, { scanned, runnable, pathImpl = path, exists = existsWd }) {
  const allowed = new Set(scanned.filter((p) => isRunnable(p, runnable)));
  const candidates = [];

  const hadSep = input.includes('/') || input.includes(pathImpl.sep);
  const mod = toModulePath(input);
  const withExt = mod.endsWith('.js') ? mod : `${mod}.js`;

  if (hadSep) {
    candidates.push(withExt);
  } else {
    for (const dir of runnable) {
      candidates.push(pathImpl.join(dir, withExt));
    }
  }

  // `allowed` is POSIX, so candidates are compared in POSIX form. A bare name
  // found in two runnable directories is ambiguous.
  const found = candidates.map(toPosix).filter((p) => allowed.has(p) && exists(p));
  if (found.length > 1) return { error: { kind: 'ambiguous', candidates: found } };
  if (found.length === 1) return { path: found[0] };

  for (const candidate of candidates) {
    const normalized = toPosix(candidate);
    if (exists(normalized) && !isRunnable(normalized, runnable)) {
      return { error: { kind: 'not-runnable', path: normalized } };
    }
  }

  return { error: { kind: 'not-found', candidates: candidates.map(toPosix) } };
}

function resolveFilePath(input) {
  const runnable = runnableDirs();
  const res = resolveRunnablePath(input, { scanned: scanFiles(), runnable });
  if (res.path) return res.path;

  const e = res.error;
  if (e.kind === 'ambiguous') {
    fatal(`"${input}" matches ${e.candidates.map(displayPath).join(' and ')} — name the directory, e.g. "${pathToModule(e.candidates[0])}".`);
  }
  if (e.kind === 'not-runnable') {
    fatal(
      `${displayPath(e.path)} is not runnable. Only modules in ${runnable.map((d) => displayPath(d) + '/').join(' and ')} can be run.`
    );
  }
  if (e.candidates.length === 1) {
    fatal(`Module not found: ${displayPath(e.candidates[0])}. Run "tgcloud status" to see your modules.`);
  }
  fatal(`Module not found in any of: ${e.candidates.map(displayPath).join(', ')}. Run "tgcloud status" to see your modules.`);
}

export function registerRun(program) {
  program
    .command('run <module> [args]')
    .description(
      'Run a module in the cloud without deploying. <module> can be a bare ' +
      'name (searched in handlers/ and endpoints/) or a path like handlers/message. ' +
      '[args] is an optional JSON5 object passed to the function ' +
      '(the payload — a Message for handlers/message). ' +
      'Read args from a file: tgcloud run module "$(cat args.json5)".'
    )
    .option('--ctx <json5>', 'JSON5 context')
    .action(async (moduleArg, positionalArgs, options) => {
      // Refresh the layout: the set of runnable directories comes from the server.
      await syncCapabilities();

      const filePath = resolveFilePath(moduleArg);
      const moduleName = pathToModule(filePath);

      const args = positionalArgs !== undefined
        ? parseJson5Inline(positionalArgs, 'Invalid JSON5 in args')
        : undefined;

      const ctx = options.ctx !== undefined
        ? parseJson5Inline(options.ctx, 'Invalid JSON5 in --ctx')
        : undefined;
      requireObject(args, 'args', '{ text: "hi" }');
      requireObject(ctx, '--ctx', '{ update: { update_id: 1 } }');

      // Every local module is sent: the server resolves imports against this
      // map only, not against the deployed state.
      const allFiles = scanFiles();
      const sources = {};
      for (const f of allFiles) {
        sources[pathToModule(f)] = readWd(f);
      }
      if (!(moduleName in sources)) {
        fatal(`Internal: ${moduleName} not in collected sources.`);
      }

      try {
        await retryOnAuthError(async () => {
          const token = await resolveToken();

          // Header first, so the spinner renders below it.
          console.log(formatRunHeader(moduleName, args));
          const spinner = createSpinner('Running...');
          spinner.start();

          let result;
          try {
            result = await runFunction(token, moduleName, sources, args, ctx);
            spinner.stop();
          } catch (err) {
            // Logs the server returned, then one error line. spinner.fail()
            // would print the message a second time.
            spinner.stop();
            const params = err.parameters || {};
            for (const line of formatRunLogs(params.log)) console.log(line);
            const ms = params.time != null ? Math.max(0, Math.round(params.time * 1000)) : null;
            const suffix = ms != null ? chalk.dim(`  ${ms}ms`) : '';
            console.log(chalk.red(`✗ ${describeServerError(err)}`) + suffix);
            throw err;
          }

          for (const line of formatRunLogs(result.log)) console.log(line);
          console.log(formatRunReturn(result.result, result.time));
        });
      } catch {
        process.exit(1);
      }
    });
}
